          r"C_{ij}(t)=\sum_n\frac{Z_i^{(n)}Z_j^{(n)*}}{2E_n}e^{-E_nt},\qquad \frac{C^{(1)}}{C^{(0)}}\propto e^{-(E_1-E_0)t}",
